-- PT110-S3-Q11. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT110-S3-Q11$batch04$ AND q.stimulus=$batch04$The present goal of the field of medicine seems to be to extend life indefinitely. Increasingly, the ability to transplant such organs as hearts, lungs, livers, and kidneys will allow us to live longer. But we can never achieve brain transplants. There are, for a start, ten million nerves running from the brain down the neck, not to mention the millions joining the brain to the sensing organs. Clearly, then, as the transplantation of organs allows more and more people to live longer, those with degenerative brain disorders will form an ever-increasing proportion of the population.$batch04$ AND q.prompt=$batch04$The argument above is based on which one of the following assumptions?$batch04$ AND q.correct_choice=$batch04$C$batch04$) THEN RAISE EXCEPTION 'Question changed: PT110-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT110-S3-Q11$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT110-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$As organ transplants let more people live longer, people with degenerative brain disorders will make up an ever-growing share of the population.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Transplants of hearts, lungs, livers and kidneys will let us live longer. Brain transplants will never be possible.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The argument treats a brain transplant as the only fix for a failing brain. But if those disorders can be cured some other way, longer lives would not leave more people with them.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: at least some degenerative brain disorders cannot be cured without a brain transplant.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT110-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$The age of the patients does not affect the argument's point about their share of the population.$batch04$), ($batch04$B$batch04$, $batch04$Whether people need a second transplant does not affect brain disorders.$batch04$), ($batch04$C$batch04$, $batch04$Negate it: *every* degenerative brain disorder can be cured without a brain transplant. Then the lack of brain transplants does not matter, and there is no reason the share would grow.$batch04$), ($batch04$D$batch04$, $batch04$How many deaths these disorders cause now does not affect whether their share will grow.$batch04$), ($batch04$E$batch04$, $batch04$Research spending is never part of the argument.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT110-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
